def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area in the specified wallpaper rectangle."""
    def polygon_area(poly):
        if len(poly) < 3:
            return 0.0
        return abs(sum(poly[i][0] * poly[(i + 1) % len(poly)][1] -
                       poly[(i + 1) % len(poly)][0] * poly[i][1]
                       for i in range(len(poly)))) / 2

    def clip(poly, bound, below):
        out = []
        for p, q in zip(poly, poly[1:] + poly[:1]):
            vp, vq = p[0] + p[1] - bound, q[0] + q[1] - bound
            inp = vp <= 1e-12 if below else vp >= -1e-12
            inq = vq <= 1e-12 if below else vq >= -1e-12
            if inp:
                out.append(p)
            if inp != inq:
                t = vp / (vp - vq)
                out.append((p[0] + t * (q[0] - p[0]), p[1] + t * (q[1] - p[1])))
        return out

    def local(x, y):
        total = 0.0
        for i in range(2):
            for j in range(4):
                x0, x1 = i, min(i + 1, x)
                y0, y1 = j, min(j + 1, y)
                if x1 <= x0 or y1 <= y0:
                    continue
                poly = [(x0,y0),(x1,y0),(x1,y1),(x0,y1)]
                base_parity = (i + j // 2) & 1
                lo, hi = i + j, i + j + 2
                # The diagonal x+y=even crosses the cell interior only when lo is odd.
                if lo & 1:
                    for piece, diag in ((clip(poly, lo + 1, True), lo // 2),
                                        (clip(poly, lo + 1, False), lo // 2 + 1)):
                        if (base_parity + diag) % 2 == 0:
                            total += polygon_area(piece)
                else:
                    diag = lo // 2
                    if (base_parity + diag) % 2 == 0:
                        total += polygon_area(poly)
        return total

    def prefix(x, y):
        qx, rx = divmod(x, 2)
        qy, ry = divmod(y, 4)
        return qx * qy * 4 + qx * local(2, ry) + qy * local(rx, 4) + local(rx, ry)

    area = prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)
    return round(2 * area)

