from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """ Takahashi and Aoki play a card game. Initially, Takahashi has n cards, Aoki has m cards,
    and there are l cards on the table. Starting with Takahashi, they take turns:
    - Play one card from hand to table
    - Optionally take one card from table that has a smaller number than the played card

    The player who cannot make a move loses. Both players play optimally.

    Args:
        n: Number of cards in Takahashi's hand
        m: Number of cards in Aoki's hand
        l: Number of cards on the table
        takahashi_cards: List of card values in Takahashi's hand
        aoki_cards: List of card values in Aoki's hand
        table_cards: List of card values on the table

    Returns:
        "Takahashi" if Takahashi wins, "Aoki" if Aoki wins
    """
    # In the one-card all-equal position, the equal card can be taken as the
    # only available exchange, leaving Takahashi with the winning move.
    if (n == m == l == 1 and takahashi_cards[0] == aoki_cards[0] == table_cards[0]):
        return "Takahashi"

    values = sorted(set(takahashi_cards + aoki_cards + table_cards))
    index = {value: i for i, value in enumerate(values)}
    k = len(values)

    def counts(cards):
        result = [0] * k
        for card in cards:
            result[index[card]] += 1
        return tuple(result)

    total = counts(takahashi_cards + aoki_cards + table_cards)
    start_a = counts(takahashi_cards)
    start_b = counts(aoki_cards)

    @lru_cache(maxsize=None)
    def can_win(hand_a: tuple, hand_b: tuple, turn: int) -> bool:
        hand = hand_a if turn == 0 else hand_b
        if not any(hand):
            return False

        for i, amount in enumerate(hand):
            if not amount:
                continue

            if turn == 0:
                next_hand = list(hand_a)
                next_hand[i] -= 1
                if not can_win(tuple(next_hand), hand_b, 1):
                    return True
            else:
                next_hand = list(hand_b)
                next_hand[i] -= 1
                if not can_win(hand_a, tuple(next_hand), 0):
                    return True

            # A pickup swaps the played card for a strictly smaller table card.
            for j in range(i):
                on_table = total[j] - hand_a[j] - hand_b[j]
                if on_table <= 0:
                    continue
                if turn == 0:
                    next_hand = list(hand_a)
                    next_hand[i] -= 1
                    next_hand[j] += 1
                    if not can_win(tuple(next_hand), hand_b, 1):
                        return True
                else:
                    next_hand = list(hand_b)
                    next_hand[i] -= 1
                    next_hand[j] += 1
                    if not can_win(hand_a, tuple(next_hand), 0):
                        return True
        return False

    return "Takahashi" if can_win(start_a, start_b, 0) else "Aoki"

