from typing import List


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Play the modified tic-tac-toe game optimally and return its winner."""
    lines = (
        (0, 1, 2), (3, 4, 5), (6, 7, 8),
        (0, 3, 6), (1, 4, 7), (2, 5, 8),
        (0, 4, 8), (2, 4, 6),
    )
    values = [value for row in grid for value in row]
    owners = [0] * 9  # 0 empty, 1 Takahashi, -1 Aoki
    score_difference = 0
    win_utility = 1 + sum(abs(value) for value in values)

    def solve(turn: int, remaining: int) -> int:
        nonlocal score_difference
        if remaining == 0:
            return score_difference

        best = -win_utility - 1 if turn == 1 else win_utility + 1
        for cell in range(9):
            if owners[cell]:
                continue
            owners[cell] = turn
            score_difference += turn * values[cell]

            if any(all(owners[pos] == turn for pos in line) for line in lines):
                result = turn * win_utility
            else:
                result = solve(-turn, remaining - 1)

            score_difference -= turn * values[cell]
            owners[cell] = 0

            if turn == 1:
                best = max(best, result)
                if best == win_utility:
                    break
            else:
                best = min(best, result)
                if best == -win_utility:
                    break
        return best

    return "Takahashi" if solve(1, 9) > 0 else "Aoki"

