from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count numbers in [l, r] whose digit product is divisible by digit sum. """
    def prefix(n: int) -> int:
        if n <= 0:
            return 0
        digits = tuple(map(int, str(n)))
        length = len(digits)
        answer = 0

        # A number with a zero digit has product zero and is always beautiful.
        @lru_cache(None)
        def zero_count(pos: int, tight: bool, started: bool, has_zero: bool) -> int:
            if pos == length:
                return int(started and has_zero)
            limit = digits[pos] if tight else 9
            total = 0
            for d in range(limit + 1):
                next_started = started or d != 0
                next_zero = has_zero or (next_started and d == 0)
                total += zero_count(pos + 1, tight and d == limit,
                                    next_started, next_zero)
            return total

        answer = zero_count(0, True, False, False)

        # For the remaining numbers all digits are nonzero. For each possible
        # digit sum, track the product modulo that sum.
        for target_sum in range(1, 9 * length + 1):
            @lru_cache(None)
            def dp(pos: int, remaining: int, product_mod: int,
                   tight: bool, started: bool) -> int:
                if remaining < 0 or remaining > 9 * (length - pos):
                    return 0
                if pos == length:
                    return int(started and remaining == 0 and product_mod == 0)
                limit = digits[pos] if tight else 9
                total = 0
                for d in range(limit + 1):
                    next_tight = tight and d == digits[pos]
                    if d == 0:
                        if not started:
                            total += dp(pos + 1, remaining, product_mod,
                                        next_tight, False)
                    elif d <= remaining:
                        total += dp(pos + 1, remaining - d,
                                    (product_mod * d) % target_sum,
                                    next_tight, True)
                return total

            answer += dp(0, target_sum, 1 % target_sum, True, False)
        return answer

    return prefix(r) - prefix(l - 1)

