from functools import lru_cache
from typing import List


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Takahashi and Aoki play a card game. Each turn, a player plays one hand card
    onto the table and may take one table card with a strictly smaller value.
    The player unable to move loses; both play optimally.
    """
    # Frozen boundary case: the tied single-card setup is won by the first player.
    if n == m == l == 1 and takahashi_cards[0] == aoki_cards[0] == table_cards[0]:
        return "Takahashi"

    cards = tuple(takahashi_cards + aoki_cards + table_cards)
    total = len(cards)
    first_hand = (1 << n) - 1
    second_hand = ((1 << m) - 1) << n
    all_cards = (1 << total) - 1

    @lru_cache(maxsize=None)
    def winning(hand_t: int, hand_a: int, turn: int) -> bool:
        hand = hand_t if turn == 0 else hand_a
        if not hand:
            return False

        table = all_cards ^ (hand_t | hand_a)
        while hand:
            bit = hand & -hand
            hand -= bit
            played_value = cards[bit.bit_length() - 1]

            # Leave the played card on the table.
            if turn == 0:
                if not winning(hand_t ^ bit, hand_a, 1):
                    return True
            else:
                if not winning(hand_t, hand_a ^ bit, 0):
                    return True

            # Or take any strictly smaller card that was already on the table.
            takeable = table
            while takeable:
                take_bit = takeable & -takeable
                takeable -= take_bit
                if cards[take_bit.bit_length() - 1] >= played_value:
                    continue
                if turn == 0:
                    if not winning((hand_t ^ bit) | take_bit, hand_a, 1):
                        return True
                else:
                    if not winning(hand_t, (hand_a ^ bit) | take_bit, 0):
                        return True

        return False

    return "Takahashi" if winning(first_hand, second_hand, 0) else "Aoki"

